#include <iostream>
#include <limits>
#include <string>

std::string tipo(long) {
    return "long";
}

std::string tipo(unsigned long) {
    return "unsigned long";
}

std::string tipo(long long) {
    return "long long";
}

std::string tipo(unsigned long long) {
    return "unsigned long long";
}

int main() {
    long corto = -1;
    long long amplio = -1;
    unsigned int cantidad = 2;
    unsigned long long cantidad_amplia = 2;

    const auto primero = corto - cantidad;
    const auto segundo = amplio - cantidad;
    const auto tercero = amplio - cantidad_amplia;

    const auto maximo_long = std::numeric_limits<unsigned long>::max();
    const auto maximo_largo = std::numeric_limits<unsigned long long>::max();
    std::cout << tipo(primero) << ':' << (primero == maximo_long - 2) << '\n';
    std::cout << tipo(segundo) << ':' << segundo << '\n';
    std::cout << tipo(tercero) << ':' << (tercero == maximo_largo - 2);
    return 0;
}

