#include <iostream>
#include <limits>

bool convertir_a_con_signo(unsigned long long dato, long long& destino) {
    // Este inicio escribe antes de comprobar; repara ese orden.
    destino = static_cast<long long>(dato);
    return destino >= 0;
}

int main() {
    int caso = 0;
    if (!(std::cin >> caso)) {
        return 1;
    }

    const long long maximo = std::numeric_limits<long long>::max();
    const unsigned long long limite = static_cast<unsigned long long>(maximo);
    const unsigned long long maximo_sin_signo =
        std::numeric_limits<unsigned long long>::max();
    unsigned long long dato = 0;
    long long esperado = 17;
    switch (caso) {
    case 1:
        dato = maximo_sin_signo;
        break;
    case 2:
        dato = 0;
        esperado = 0;
        break;
    case 3:
        dato = limite;
        esperado = maximo;
        break;
    case 4:
        dato = limite + 1;
        break;
    case 5:
        dato = 42;
        esperado = 42;
        break;
    case 6:
        dato = limite - 1;
        esperado = maximo - 1;
        break;
    case 7:
        dato = maximo_sin_signo - 1;
        break;
    default:
        return 1;
    }

    long long destino = 17;
    const bool aceptado = convertir_a_con_signo(dato, destino);
    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Coincide=" << (destino == esperado) << '\n';
    std::cout << "Conservado=" << (destino == 17) << '\n';
    return 0;
}

