#include <iostream>
#include <limits>

bool convertir_a_con_signo(unsigned long long dato, long long& destino) {
    const long long maximo = std::numeric_limits<long long>::max();
    const unsigned long long limite = static_cast<unsigned long long>(maximo);
    if (dato > limite) {
        return false;
    }

    destino = static_cast<long long>(dato);
    return true;
}

int main() {
    long long destino = 17;
    const unsigned long long maximo =
        std::numeric_limits<unsigned long long>::max();

    const bool primero = convertir_a_con_signo(42, destino);
    std::cout << primero << ':' << destino << '\n';

    const bool segundo = convertir_a_con_signo(maximo, destino);
    std::cout << segundo << ':' << destino << '\n';

    const bool tercero = convertir_a_con_signo(0, destino);
    std::cout << tercero << ':' << destino << '\n';

    const bool cuarto = convertir_a_con_signo(maximo, destino);
    std::cout << cuarto << ':' << destino;
    return 0;
}
